from collections import deque

def topological_sort(nodes, adj):
    in_degree = {n: 0 for n in nodes}
    for node in nodes:
        for nxt in adj.get(node, []):
            in_degree[nxt] += 1

    # Everything that depends on nothing can start immediately.
    ready = deque(n for n in nodes if in_degree[n] == 0)
    order = []

    while ready:
        node = ready.popleft()
        order.append(node)

        for nxt in adj.get(node, []):
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                ready.append(nxt)   # now unblocked

    # Anything left still has an unmet dependency, which on a finite
    # graph can only mean those nodes depend on each other in a loop.
    if len(order) != len(nodes):
        raise ValueError("Cycle detected: no valid order exists")

    return order

