std::vector<std::string> topologicalSort(
    const std::vector<std::string>& nodes,
    const std::map<std::string, std::vector<std::string>>& adj) {
    std::map<std::string, int> inDegree;
    for (const std::string& n : nodes) inDegree[n] = 0;

    for (const std::string& node : nodes) {
        auto it = adj.find(node);
        if (it == adj.end()) continue;
        for (const std::string& next : it->second) inDegree[next]++;
    }

    // Everything that depends on nothing can start immediately.
    std::queue<std::string> ready;
    for (const std::string& n : nodes) {
        if (inDegree[n] == 0) ready.push(n);
    }

    std::vector<std::string> order;
    while (!ready.empty()) {
        std::string node = ready.front();
        ready.pop();
        order.push_back(node);

        auto it = adj.find(node);
        if (it == adj.end()) continue;
        for (const std::string& next : it->second) {
            if (--inDegree[next] == 0) ready.push(next);  // now unblocked
        }
    }

    // Anything left still has an unmet dependency, which on a finite
    // graph can only mean those nodes depend on each other in a loop.
    if (order.size() != nodes.size()) {
        throw std::runtime_error("Cycle detected: no valid order exists");
    }
    return order;
}

