enum class State { Unseen, Visiting, Done };

std::vector<std::string> topoDfs(
    const std::vector<std::string>& nodes,
    const std::map<std::string, std::vector<std::string>>& adj) {
    std::map<std::string, State> state;
    for (const std::string& n : nodes) state[n] = State::Unseen;
    std::vector<std::string> finished;

    // std::function so the lambda can call itself.
    std::function<void(const std::string&)> visit = [&](const std::string& node) {
        if (state[node] == State::Done) return;
        // Meeting a node we're still in the middle of means we
        // walked in a circle and came back to it.
        if (state[node] == State::Visiting) throw std::runtime_error("Cycle detected");

        state[node] = State::Visiting;
        auto it = adj.find(node);
        if (it != adj.end()) {
            for (const std::string& next : it->second) visit(next);
        }
        state[node] = State::Done;
        finished.push_back(node);
    };

    for (const std::string& node : nodes) visit(node);

    std::reverse(finished.begin(), finished.end());
    return finished;
}
